   127  static void
   128  ary_modify(mrb_state *mrb, struct RArray *a)
   129  {
   130    ary_modify_check(mrb, a);
   131
   132    if (ARY_SHARED_P(a)) {
   133      mrb_shared_array *shared = a->as.heap.aux.shared;
   134
   135      if (shared->refcnt == 1 && a->as.heap.ptr == shared->ptr) {
   136        a->as.heap.ptr = shared->ptr;
   137        a->as.heap.aux.capa = a->as.heap.len;
   138        mrb_free(mrb, shared);
   139      }
   140      else {
   141        mrb_value *ptr, *p;
   142        mrb_int len;
   143
   144        p = a->as.heap.ptr;
   145        len = a->as.heap.len * sizeof(mrb_value);
   146        ptr = (mrb_value *)mrb_malloc(mrb, len);
   147        if (p) {
   148          array_copy(ptr, p, a->as.heap.len);
   149        }
   150        a->as.heap.ptr = ptr;
   151        a->as.heap.aux.capa = a->as.heap.len;
   152        mrb_ary_decref(mrb, shared);
   153      }
   154      ARY_UNSET_SHARED_FLAG(a);
   155    }
   156  }
