   166  ary_make_shared(mrb_state *mrb, struct RArray *a)
   167  {
   168    if (!ARY_SHARED_P(a) && !ARY_EMBED_P(a)) {
   169      mrb_shared_array *shared = (mrb_shared_array *)mrb_malloc(mrb, sizeof(mrb_shared_array));
   170      mrb_value *ptr = a->as.heap.ptr;
   171      mrb_int len = a->as.heap.len;
   172
   173      shared->refcnt = 1;
   174      if (a->as.heap.aux.capa > len) {
   175        a->as.heap.ptr = shared->ptr = (mrb_value *)mrb_realloc(mrb, ptr, sizeof(mrb_value)*len+1);
   176      }
   177      else {
   178        shared->ptr = ptr;
   179      }
   180      shared->len = len;
