   561      return val;
   562    }
   563    if (len > ARY_SHIFT_SHARED_MIN) {
   564      ary_make_shared(mrb, a);
   565      goto L_SHIFT;
   566    }
   567    else {
   568      mrb_value *ptr = ARY_PTR(a);
   569      mrb_int size = len;
   570
   571      val = *ptr;
   572      while (--size) {
