   581  static mrb_value
   582  mrb_ary_shift_m(mrb_state *mrb, mrb_value self)
   583  {
   584    struct RArray *a = mrb_ary_ptr(self);
   585    mrb_int len = ARY_LEN(a);
   586    mrb_int n;
   587    mrb_value val;
   588
   589    if (mrb_get_args(mrb, "|i", &n) == 0) {
   590      return mrb_ary_shift(mrb, self);
   591    };
   592    ary_modify_check(mrb, a);
   593    if (len == 0 || n == 0) return mrb_ary_new(mrb);
   594    if (n < 0) mrb_raise(mrb, E_ARGUMENT_ERROR, "negative array shift");
   595    if (n > len) n = len;
   596    val = mrb_ary_new_from_values(mrb, n, ARY_PTR(a));
   597    if (ARY_SHARED_P(a)) {
   598    L_SHIFT:
   599      a->as.heap.ptr+=n;
   600      a->as.heap.len-=n;
   601      return val;
   602    }
   603    if (len > ARY_SHIFT_SHARED_MIN) {
   604      ary_make_shared(mrb, a);
   605      goto L_SHIFT;
   606    }
   607    else if (len == n) {
   608      ARY_SET_LEN(a, 0);
   609    }
   610    else {
   611      mrb_value *ptr = ARY_PTR(a);
   612      mrb_int size = len-n;
   613
   614      while (size--) {
   615        *ptr = *(ptr+n);
   616        ++ptr;
   617      }
   618      ARY_SET_LEN(a, len-n);
   619    }
   620    return val;
   621  }
