   624     item = 0
   625     self.unshift item
   626     p self #=> [0, 1, 2, 3] */
   627  MRB_API mrb_value
   628  mrb_ary_unshift(mrb_state *mrb, mrb_value self, mrb_value item)
   629  {
   630    struct RArray *a = mrb_ary_ptr(self);
   631    mrb_int len = ARY_LEN(a);
   632
   633    if (ARY_SHARED_P(a)
   634        && a->as.heap.aux.shared->refcnt == 1 /* shared only referenced from this array */
   635        && a->as.heap.ptr - a->as.heap.aux.shared->ptr >= 1) /* there's room for unshifted item */ {
   636      a->as.heap.ptr--;
   637      a->as.heap.ptr[0] = item;
   638    }
   639    else {
   640      mrb_value *ptr;
   641
   642      ary_modify(mrb, a);
   643      if (ARY_CAPA(a) < len + 1)
   644        ary_expand_capa(mrb, a, len + 1);
   645      ptr = ARY_PTR(a);
   646      value_move(ptr + 1, ptr, len);
   647      ptr[0] = item;
   648    }
   649    ARY_SET_LEN(a, len+1);
   650    mrb_field_write_barrier_value(mrb, (struct RBasic*)a, item);
   651
   652    return self;
   653  }
