   655  static mrb_value
   656  mrb_ary_unshift_m(mrb_state *mrb, mrb_value self)
   657  {
   658    struct RArray *a = mrb_ary_ptr(self);
   659    const mrb_value *vals;
   660    mrb_value *ptr;
   661    mrb_int alen, len;
   662
   663    mrb_get_args(mrb, "*!", &vals, &alen);
   664    if (alen == 0) {
   665      ary_modify_check(mrb, a);
   666      return self;
   667    }
   668    len = ARY_LEN(a);
   669    if (alen > ARY_MAX_SIZE - len) {
   670      mrb_raise(mrb, E_ARGUMENT_ERROR, "array size too big");
   671    }
   672    if (ARY_SHARED_P(a)
   673        && a->as.heap.aux.shared->refcnt == 1 /* shared only referenced from this array */
   674        && a->as.heap.ptr - a->as.heap.aux.shared->ptr >= alen) /* there's room for unshifted item */ {
   675      ary_modify_check(mrb, a);
   676      a->as.heap.ptr -= alen;
   677      ptr = a->as.heap.ptr;
   678    }
   679    else {
   680      mrb_bool same = vals == ARY_PTR(a);
   681      ary_modify(mrb, a);
   682      if (ARY_CAPA(a) < len + alen)
   683        ary_expand_capa(mrb, a, len + alen);
   684      ptr = ARY_PTR(a);
   685      value_move(ptr + alen, ptr, len);
   686      if (same) vals = ptr;
   687    }
   688    array_copy(ptr, vals, alen);
   689    ARY_SET_LEN(a, len+alen);
   690    while (alen--) {
   691      mrb_field_write_barrier_value(mrb, (struct RBasic*)a, vals[alen]);
   692    }
   693
   694    return self;
   695  }
